-- Asegurar constraint único en codigo para el ON CONFLICT
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.table_constraints
    WHERE table_name = 'gift_cards' AND constraint_name = 'gift_cards_codigo_unique'
  ) THEN
    ALTER TABLE gift_cards ADD CONSTRAINT gift_cards_codigo_unique UNIQUE (codigo);
  END IF;
END $$;

